# name:: If generated by the CLI this will be "cli", otherwise user-provided
# encryptedToken:: This is the token encrypted using the ENCRYPTION_KEY
# obfuscatedToken:: This is shown in the UI, with ********
# hashedToken:: This is used to find the token in the database
# expiresAt:: After this the token no longer authenticates. Null means it never expires.
# idleTimeoutSeconds:: Set on CLI login tokens: they stop authenticating this many seconds after their last use
#   (or creation, if never used). Null means no idle limit.
# expiryReminderSentAt:: When the "about to expire" email was sent. Set before sending, so it's sent at most once.
# expiredNoticeSentAt:: When the "has expired" email was sent. Set before sending, so it's sent at most once.
class PersonalAccessToken < ApplicationRecord
  self.table_name = "PersonalAccessToken"
  self.implicit_order_column = "createdAt"

  attribute :id, default: -> { Cuid.generate }
  alias_attribute :created_at, :createdAt
  alias_attribute :updated_at, :updatedAt

  validates :name, presence: true
  validates :encryptedToken, exclusion: { in: [ nil ] }
  validates :obfuscatedToken, presence: true
  validates :hashedToken, presence: true, uniqueness: true

  belongs_to :user, foreign_key: "userId", inverse_of: :personal_access_tokens
  belongs_to :oauth_client, class_name: "OAuthClient", foreign_key: "oauthClientId", optional: true,
                            inverse_of: :personal_access_tokens
  has_many :authorization_codes, foreign_key: "personalAccessTokenId", inverse_of: :personal_access_token,
                                 dependent: :destroy
  has_many :oauth_refresh_tokens, class_name: "OAuthRefreshToken", foreign_key: "personalAccessTokenId",
                                  inverse_of: :personal_access_token, dependent: :destroy
end
